ProbabilityTheory.meas_ge_le_variance_div_sq.{u_1} {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω}
  [MeasureTheory.IsFiniteMeasure μ] {X : Ω → ℝ} (hX : MeasureTheory.MemLp X 2 μ) {c : ℝ} (hc : 0 < c) :
  μ {ω | c ≤ |X ω - ∫ (x : Ω), X x ∂μ|} ≤ ENNReal.ofReal (ProbabilityTheory.variance X μ / c ^ 2)

ProbabilityTheory.indepFun_iff_map_prod_eq_prod_map_map.{u_1, u_6, u_7} {Ω : Type u_1} {β : Type u_6} {β' : Type u_7}
  {_mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {f : Ω → β} {g : Ω → β'} {mβ : MeasurableSpace β}
  {mβ' : MeasurableSpace β'} [MeasureTheory.IsFiniteMeasure μ] (hf : AEMeasurable f μ) (hg : AEMeasurable g μ) :
  ProbabilityTheory.IndepFun f g μ ↔
    MeasureTheory.Measure.map (fun ω => (f ω, g ω)) μ =
      (MeasureTheory.Measure.map f μ).prod (MeasureTheory.Measure.map g μ)

Lagrange.eval_interpolate_at_node.{u_1, u_2} {F : Type u_1} [Field F] {ι : Type u_2} [DecidableEq ι] {s : Finset ι}
  {i : ι} {v : ι → F} (r : ι → F) (hvs : Set.InjOn v ↑s) (hi : i ∈ s) :
  Polynomial.eval (v i) ((Lagrange.interpolate s v) r) = r i

Lagrange.eq_interpolate.{u_1, u_2} {F : Type u_1} [Field F] {ι : Type u_2} [DecidableEq ι] {s : Finset ι} {v : ι → F}
  {f : Polynomial F} (hvs : Set.InjOn v ↑s) (degree_f_lt : f.degree < ↑s.card) :
  f = (Lagrange.interpolate s v) fun i => Polynomial.eval (v i) f
